package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;
class ReportPreparationInputProfileTest {
 boolean mysql(){return false;}
 ReportInputWriterAdmissionTest nativeFixture(){return new ReportInputWriterAdmissionTest(){@Override boolean mysql(){return ReportPreparationInputProfileTest.this.mysql();}};}
 FrozenGenerationSettings settings(){return new FrozenGenerationSettings(1,List.of("Fictional topic"),List.of());}
 ReportPreparationInputProfile.Complete full(ReportInputWriterAdmissionTest.Period x){return ReportPreparationInputProfile.create(x.captured(),settings(),"fictional-new-report-content",null,false);}
 @Test void ActualPeriodFactsProduceCompleteRecoverableOriginalCommandAndSelectedReferences(){var x=nativeFixture().admitted();var c=full(x);var snapshot=CanonicalJson.parse(c.snapshotJson());var recovered=ReportPreparationInputProfile.complete(snapshot);assertEquals(c.snapshotJson(),recovered.snapshotJson());assertEquals(c.command().applicationContext().json(),recovered.command().applicationContext().json());assertEquals(x.captured().dependencies(),c.command().dependencies());assertEquals(1,c.command().applicationContext().referenceTargets().size());assertEquals(1,c.command().applicationContext().input("fictional-new-root","fictional-attempt",CanonicalJson.hash(CanonicalJson.Domain.INPUT,snapshot),0).allowedCitationIds().size());assertNull(c.command().applicationContext().baseContentRevision());assertEquals(1,x.nativeData().f.h.h.f.sends);var base=x.nativeData().f.h.h.f;base.writes.execute(base.action("fictional-original-profile-admit"),k->null,a->{assertTrue(x.admission().asWriterSource(x.captured()).snapshot(c.command(),x.captured().cutoff()).complete());return true;});}
 @Test void ActualDailyFactsBuildOnlyOriginalSelectedCitationClosure()throws Exception{var f=nativeFixture().daily();var base=f.data.nativeData().fixture().f();var reader=new ReportInputCaptureService(f.service,mock(ReportPeriodInputComponentService.class),base.tx);var service=new ReportInputWriterAdmissionService(base.source,base.tx,reader);var day=f.data.nativeData().fixture().day();var capture=service.capture(new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day),f.data.nativeData().cutoff());var full=ReportPreparationInputProfile.create(capture,settings(),"fictional-daily-report",7L,false);assertEquals(7L,full.command().applicationContext().baseContentRevision());assertEquals(1,full.command().applicationContext().referenceTargets().size());assertEquals(settings(),FrozenGenerationSettings.read(CanonicalJson.parse(full.snapshotJson()).get(FrozenGenerationSettings.FIELD)));assertEquals(2,base.sends);}
 @Test void BlockedOriginalIsRecordedExcludedAndNeverRetainsUnselectedCitations(){var x=nativeFixture().admitted();var base=x.nativeData().f.h.h.f;base.jdbc.update("UPDATE contents SET state='blocked'");var fresh=x.admission().capture(x.captured().scope(),x.captured().cutoff());var full=ReportPreparationInputProfile.create(fresh,settings(),"fictional-empty-report",null,false);assertTrue(CanonicalJson.parse(full.snapshotJson()).get("members").isEmpty());assertTrue(full.command().applicationContext().referenceTargets().isEmpty());assertEquals("no_input",CanonicalJson.parse(full.snapshotJson()).get("coverage_state").asText());assertTrue(CanonicalJson.parse(full.snapshotJson()).get(com.lianxibu.site.service.content.ReportInputProfile.FIELD).get("coverage").get("no_update_dates").isEmpty());}
 @Test void OriginalSettingsScopeDependencyClosureAndClosedCommandCannotBeChanged(){var x=nativeFixture().admitted();var full=full(x);var root=(ObjectNode)CanonicalJson.parse(full.snapshotJson());root.put("settings_hash","b".repeat(64));assertThrows(RuntimeException.class,()->ReportPreparationInputProfile.complete(root));var scope=(ObjectNode)CanonicalJson.parse(full.snapshotJson());scope.put("logical_key","fictional-alias");assertThrows(RuntimeException.class,()->ReportPreparationInputProfile.complete(scope));var deps=(ObjectNode)CanonicalJson.parse(full.snapshotJson());((ObjectNode)deps.get(ReportPreparationInputProfile.FIELD).get("dependencies").get(0)).put("state","failed");assertThrows(RuntimeException.class,()->ReportPreparationInputProfile.complete(deps));var missing=(ObjectNode)CanonicalJson.parse(full.snapshotJson());((ObjectNode)missing.get(ReportPreparationInputProfile.FIELD)).putArray("expected_dependencies");assertThrows(RuntimeException.class,()->ReportPreparationInputProfile.complete(missing));var extra=(ObjectNode)CanonicalJson.parse(full.snapshotJson());((ObjectNode)extra.get(ReportPreparationInputProfile.FIELD)).put("invented_authority",true);assertThrows(RuntimeException.class,()->ReportPreparationInputProfile.complete(extra));}
 @Test void OriginalFactsStayIndependentOfLaterCurrentDataAndPureProfileGrantsNoAdmission(){var x=nativeFixture().admitted();var original=full(x);x.nativeData().f.h.h.f.jdbc.update("UPDATE contents SET state='blocked',body_json='{}'");assertEquals(original.snapshotJson(),ReportPreparationInputProfile.complete(CanonicalJson.parse(original.snapshotJson())).snapshotJson());var base=x.nativeData().f.h.h.f;assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-stale-profile"),k->null,a->x.admission().asWriterSource(x.captured()).snapshot(original.command(),x.captured().cutoff())));assertTrue(original.toString().contains("redacted"));}
}
